var toggleTheme=(()=>{let a=`theme-storage`,b=`light`,c=`dark`;if(localStorage.getItem(a)===b){setTheme(c);updateItemToggleTheme()}else if(localStorage.getItem(a)===c){setTheme(b);updateItemToggleTheme()}});var getSavedTheme=(()=>{let a=localStorage.getItem(`theme-storage`);if(!a){if(window.matchMedia&&window.matchMedia(`(prefers-color-scheme: dark)`).matches){a=`dark`}else{a=`light`}};return a});var setTheme=(a=>{localStorage.setItem(`theme-storage`,a)});var updateItemToggleTheme=(()=>{let i=`none`,h=`inline-block`,f=`light`,g=`dark`;let a=getSavedTheme();const b=document.getElementById(`darkModeStyle`);if(b){b.disabled=a===f};const c=document.getElementById(`sun-icon`);const d=document.getElementById(`moon-icon`);if(c&&d){c.style.display=a===g?h:i;d.style.display=a===f?h:i};let e=document.querySelector(`html`);if(a===g){e.classList.remove(f);e.classList.add(g)}else if(a===f){e.classList.remove(g);e.classList.add(f)}});updateItemToggleTheme()